382	    @Test
383	    void 版本冲突串行化分段与封榜竞争() throws Exception {
384	        createRace();
385	        registerRunner("a", 10_000L, 1, "req-a");
386	        configure(2, "req-cfg", "c1", "1"); // 当前版本 3
387	
388	        int threads = 8;
389	        java.util.concurrent.ExecutorService pool =
390	                java.util.concurrent.Executors.newFixedThreadPool(threads);
391	        java.util.concurrent.CountDownLatch start = new java.util.concurrent.CountDownLatch(1);
392	        java.util.concurrent.atomic.AtomicInteger timingOk = new java.util.concurrent.atomic.AtomicInteger();
393	        java.util.concurrent.atomic.AtomicInteger sealOk = new java.util.concurrent.atomic.AtomicInteger();
394	        java.util.concurrent.atomic.AtomicInteger conflicts = new java.util.concurrent.atomic.AtomicInteger();
395	        try {
396	            var futures = new java.util.ArrayList<java.util.concurrent.Future<?>>();
397	            for (int i = 0; i < threads; i++) {
398	                final int index = i;
399	                futures.add(pool.submit(() -> {
400	                    start.await();
401	                    try {
402	                        if (index % 2 == 0) {
403	                            raceService.submitTiming(RACE, "a", new SubmitTimingRequest(
404	                                    "t-conc-" + index, "c1", 100L + index, 3, "req-conc-" + index));
405	                            timingOk.incrementAndGet();
406	                        } else {
407	                            raceService.sealRace(RACE, new SealRaceRequest(3, "req-seal-" + index));
408	                            sealOk.incrementAndGet();
409	                        }
410	                    } catch (ConflictException ex) {
411	                        conflicts.incrementAndGet();
412	                    }
413	                    return null;
414	                }));
415	            }
416	            start.countDown();
417	            for (java.util.concurrent.Future<?> future : futures) {
418	                future.get(30, java.util.concurrent.TimeUnit.SECONDS);
419	            }
420	        } finally {
421	            pool.shutdownNow();
422	        }
423	
424	        // 同一版本只允许一个写成功（要么一条分段，要么封榜）
425	        assertThat(timingOk.get() + sealOk.get()).isEqualTo(1);
426	        assertThat(conflicts.get()).isEqualTo(threads - 1);
427	        RaceRow race = repository.findRace(RACE).orElseThrow();
428	        assertThat(race.version()).isEqualTo(4);
429	        if (sealOk.get() == 1) {
430	            assertThat(race.status()).isEqualTo(RaceStatus.SEALED);
431	            assertThat(repository.findAllTimings(RACE)).isEmpty();
432	        } else {
433	            assertThat(race.status()).isEqualTo(RaceStatus.OPEN);
434	            assertThat(repository.findAllTimings(RACE)).hasSize(1);
435	        }
436	    }
437	}
