```java
@Transactional
public ServiceResult startMedicalHold(String raceId, String bib, StartMedicalHoldRequest request) {
    return withIdempotency(request.requestId(), "START_MEDICAL_HOLD",
        orderedParams("raceId", raceId, "bib", bib, "holdId", request.holdId(),
            "startAt", request.startAt(), "reason", request.reason(),
            "medicalRole", request.medicalRole(), "expectedVersion", request.expectedVersion()),
        () -> {
            RaceRow race = requireOpenRace(raceId, request.expectedVersion());
            RunnerRow runner = requireRunner(raceId, bib);
            requireNotDisqualified(raceId, bib, "开始医疗暂停");
            if (repository.findActiveHold(raceId, bib).isPresent()) {
                throw new ConflictException("选手已存在生效中的医疗暂停: " + bib);
            }
            long now = clock.millis();
            bumpVersion(race, request.expectedVersion());
            MedicalHoldRow row = new MedicalHoldRow(request.holdId(), raceId, bib,
                request.startAt(), null, request.reason(), request.medicalRole(), now,
                null, null, null, MedicalHoldStatus.ACTIVE, bib, now);
            try {
                repository.insertHold(row);
            } catch (DuplicateKeyException ex) {
                if (constraintMatches(ex, "uk_medical_hold_active")) {
                    throw new ConflictException("选手已存在生效中的医疗暂停: " + bib);
                }
                throw new ConflictException("医疗暂停ID已存在: " + request.holdId());
            }
            return ServiceResult.created(ResponseMapper.toMedicalHoldResponse(
                repository.findHold(request.holdId()).orElseThrow()));
        });
}
```

resume:

```java
@Transactional
public ServiceResult resumeMedicalHold(String raceId, String bib, String holdId, ResumeMedicalHoldRequest request) {
    return withIdempotency(request.requestId(), "RESUME_MEDICAL_HOLD",
        orderedParams(...),
        () -> {
            RaceRow race = requireOpenRace(raceId, request.expectedVersion());
            RunnerRow runner = requireRunner(raceId, bib);
            requireNotDisqualified(raceId, bib, "恢复医疗暂停");
            MedicalHoldRow hold = repository.findHold(holdId)
                .orElseThrow(() -> new NotFoundException("医疗暂停不存在: " + holdId));
            if (!hold.raceId().equals(raceId) || !hold.bib().equals(bib)) {
                throw new NotFoundException("医疗暂停不属于该选手: " + holdId);
            }
            if (hold.status() != MedicalHoldStatus.ACTIVE) {
                throw new ConflictException("医疗暂停已恢复: " + holdId);
            }
            if (request.endAt() <= hold.startAt()) {
                throw new BadRequestException("结束时刻必须晚于开始时刻: startAt=" + hold.startAt()
                    + ", endAt=" + request.endAt() + ", 差额=" + (request.endAt() - hold.startAt()) + "ms");
            }
            if (request.medicalRole().equals(hold.startedBy())) {
                throw new UnprocessableEntityException("恢复须由不同医疗角色确认适赛: " + request.medicalRole());
            }
            if (runner.finishTimeMs() != null
                    && runner.updatedAt() >= hold.startAt()
                    && runner.updatedAt() < request.endAt()) {
                throw new UnprocessableEntityException(
                    "暂停期间存在终点计时，须先按既有规则裁定完赛状态: finishRecordedAt=" + runner.updatedAt()
                    + ", 暂停区间=[" + hold.startAt() + ", " + request.endAt() + ")");
            }
            long now = clock.millis();
            bumpVersion(race, request.expectedVersion());
            int updated = repository.resumeHold(holdId, request.endAt(), request.medicalRole(),
                request.fitnessConclusion(), now);
            if (updated == 0) {
                throw new ConflictException("医疗暂停已恢复: " + holdId);
            }
            return ServiceResult.ok(ResponseMapper.toMedicalHoldResponse(
                repository.findHold(holdId).orElseThrow()));
        });
}
```

